<script>
(function() {
  const MIN = 1, MAX = 100;
  let secret = Math.floor(Math.random() * (MAX - MIN + 1)) + MIN;
  let attempts = 0;
  let gameOver = false;

  const guessInput = document.getElementById('guessInput');
  const guessBtn = document.getElementById('guessBtn');
  const resetBtn = document.getElementById('resetBtn');
  const message = document.getElementById('message');
  const historyList = document.getElementById('historyList');
  const attemptsSpan = document.getElementById('attempts');
  const rangeInfo = document.getElementById('rangeInfo');
  const hiddenNum = document.getElementById('hiddenNum');

  function updateUI() {
    attemptsSpan.textContent = `已猜 ${attempts} 次`;
  }

  function addTag(value, type) {
    const span = document.createElement('span');
    span.className = `tag ${type}`;
    span.textContent = type === 'correct' ? `🎉 ${value}` : `${value} ${type === 'low' ? '⬆️' : '⬇️'}`;
    historyList.appendChild(span);
    historyList.scrollTo({ left: historyList.scrollWidth, behavior: 'smooth' });
  }

  function setMessage(text, type) {
    message.textContent = text;
    message.className = 'message ' + (type || 'hint');
  }

  function resetGame() {
    secret = Math.floor(Math.random() * (MAX - MIN + 1)) + MIN;
    attempts = 0;
    gameOver = false;
    historyList.innerHTML = '';
    guessInput.value = '';
    guessInput.disabled = false;
